FAQ=[
('What is included in the price?','Unlimited calling within the destinations included in your chosen plan, a dedicated caller ID, CRM integration, Power Dialer, Call Logs & Analytics, incoming and outgoing calling, and call recording. There is no setup fee or extra charge added to the listed price.'),
('How does USA and Canada team pricing work?','One user is $22 per month. Two users are $38 total per month. Three or more users are $15 per user per month. For example, five users cost $75 per month.'),
('Do you offer a free trial?','No. You can request a 15-minute guided demonstration instead. The team will confirm your demo timing on WhatsApp.'),
('How quickly is my account activated?','The stated activation time is 10-15 minutes after payment confirmation, available 24/7. Number availability and any required verification should be confirmed before you pay.'),
('When is customer support available?','Monday-Friday, 3 PM to 3 AM the following morning, Pakistan Time (PKT / UTC+5). The Friday shift ends on Saturday at 3 AM. Account activation availability is separate from support hours.'),
('How do I pay?','Choose Bank Transfer, USDT or Credit / Debit Card via Stripe as your preference. Our team sends the appropriate payment instructions or secure link on WhatsApp. This website does not collect card details or take payment at enquiry submission.'),
('Is there a monthly minute cap?','No fixed monthly minute cap has been specified for these plans. Unlimited calling applies to the destinations included in your chosen plan and lawful business use. Ask us to confirm your required destination list before payment.'),
('Can I choose a particular phone number?','Tell us your preferred country, area or number type. Number availability and verification requirements are confirmed by the team. Submitting a request does not reserve a number.'),
('Are SMS, voicemail and AI features included?','No. SMS and voicemail are not currently available. AI summaries/transcripts, live captions and Floating Phone are planned for a future dialer update, but are not currently available or included.'),
('Where do existing customers sign in?','Use Client Login to open dialnytics.co.uk. This marketing website and its enquiries admin are separate from your calling account.'),
('What happens after I submit a form?','Your request is saved with a reference number. You can then open a prepared WhatsApp message. Your saved request remains available to the team even if you do not send the WhatsApp message.'),
('What is your refund policy?','Final refund and cancellation terms have not yet been published. Request the applicable written terms before making payment. This site does not promise either automatic refunds or a blanket no-refund policy.'),
]

add('/about/','Built around the next conversation.','About Dialnytics','Dialnytics brings business calling and lead workflows together, with straightforward country pricing and a human setup process.', [('Who operates Dialnytics','Dialnytics is operated by PRIME MSM LIMITED. Use the company and contact details below to get in touch.',['Company number: '+BUSINESS['company_number'],'Registered office: '+BUSINESS['address'],'Business contact: '+BUSINESS['email']]),('Two websites. Two different jobs.','dialnytics.uk explains plans, collects requests and helps you choose a service. Existing customers use dialnytics.co.uk for the actual dialer.',['Marketing enquiries are not calling accounts','Payment is arranged with the team','No change to the existing dialer from this website']),('A clear offer','Included tools and payable prices should be easy to understand. That is why recording and Power Dialer are included rather than billed as add-ons.',['No setup charge','No extra plan charges','15-minute guided demos, no free trial'])])
add('/how-it-works/','From your plan to your first call.','Getting started','Choose your destinations and users, send an enquiry, confirm the details with our team, then arrange payment.', [('01 / Choose your plan','Use the calculator to see your listed monthly price. European local numbers and custom combinations are quoted before you pay.',['Choose a destination','Set your team size','Review all included tools']),('02 / Send your details','Your form is saved with a reference number. Continue to WhatsApp to discuss number preferences and activation.',['No card details on the form','No automatic dialer account','Your request stays in our inbox']),('03 / Confirm and pay','Confirm number availability, verification requirements and the applicable service terms first. Payment is arranged by Bank Transfer, USDT or a secure Stripe link.',['No extra charges added to listed plans','No automatic payment at submission','Ask for the final refund terms in writing']),('04 / Start calling','Account activation is offered 24/7, with a stated 10-15 minute activation time after payment confirmation.',['Receive your login details','Test your headset and browser','Support: Mon-Fri, 3 PM-3 AM PKT'])])
add('/payments/','Choose how you would like to pay.','Payments','Payments are arranged manually through our team. Sending an enquiry is not a payment and does not activate an account.', [('Bank Transfer','Request current beneficiary details from the team. Check the business identity before making a transfer.',['Payment instructions provided securely','No bank details invented on this website','Payment must be confirmed before activation']),('USDT','Confirm the wallet address, blockchain network and payable amount directly with the authorised team before sending.',['No wallet address published here','Do not assume networks are interchangeable','Never send a wallet recovery phrase']),('Credit / Debit Card via Stripe','The team can provide an appropriate secure payment link. Enter card information only on the genuine payment provider page.',['Card payment preference recorded','No card number or CVV collected here','No payment success claimed by this website'])])
add('/system-requirements/','Get your browser ready to call.','Browser guide','Use an up-to-date browser, a working microphone and a reliable connection. A short test before a calling session is better than guessing.', [('Before you start','Check microphone permissions and your selected input/output devices. Use a headset where practical.',['Allow the dialer to use the microphone','Check the correct speaker and mic are selected','Keep the browser and operating system updated']),('A connection that stays with you','A stable connection matters for live audio. Confirm that your organisation allows browser calling traffic.',['Avoid changing networks mid-call','Ask IT about blocked traffic','Test an incoming and outgoing call']),('Mobile and background behaviour','This marketing website adapts to screen size. Browser calling in the separate dialer can still be affected by device permissions, sleep and background restrictions.',['Keep the dialer foregrounded during tests','Do not treat a closed tab as an available phone','Discuss your exact device workflow in a demo'])])
add('/product/overview/','One workspace. Every conversation in context.','Product overview','Start with the seven confirmed included tools. Explore what they do, then see the workflow in a guided demo.', [('Your calling essentials','Unlimited calling in your selected plan destinations, a dedicated caller ID, and incoming/outgoing browser calling.',['Browser calling','Dedicated business identity','Incoming and outgoing history']),('Your lead workflow','Work with CRM records and selected Power Dialer queues, with scripts, outcomes and call notes.',['CRM integration','Power Dialer included','Recording included']),('What is not available yet','SMS and voicemail are not currently available. AI summaries/transcripts, live captions and Floating Phone are planned, not live.',['No unavailable features included in pricing','No fabricated testimonials','No self-service payment or automatic user creation'])],group='overview')

